from review import card,save,DATE

def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2625';_,c=card(i);refs=c['references'];refs[0]['locator']='RANDOM 2023, article 51: Theorem 1, Definition 2 and Conjecture 23 read. Restored both promise cases and the independent-set conclusion; the proved almost-coloring theorem explicitly uses randomized reductions.'
save(i,dict(title='Almost 3-colorable graphs versus graphs with no large independent set',formal='For every fixed pair of constants 0<η<1 and 0<ε<(1−η)/3, is it NP-hard to distinguish graphs G on N vertices in which an induced subgraph on at least (1−η)N vertices is properly 3-colorable from graphs G with independence number α(G)<εN? This is the nonoverlapping promise range of the source’s Conjecture 23, whose intended demand is hardness for arbitrarily small positive η and ε.',definitions='G is a finite nonempty simple undirected graph, represented by its adjacency matrix or edge list. An independent set is a set of vertices containing no edge; α(G) is its maximum size. The subgraph induced by U⊆V(G) contains all edges of G with both endpoints in U. It is properly 3-colorable if a map U→{1,2,3} gives adjacent vertices different labels. Define iCol₃(G)=N^{−1}max{|U|:G[U] is 3-colorable}. The yes case is iCol₃(G)≥1−η, and the no case is α(G)/N<ε. Fractions refer to vertices, not edges or color classes of a fixed coloring. The parameters ε,η are fixed before the reduction and are not part of the graph input. In the usual deterministic NP-hardness formulation, for each pair there must be a deterministic polynomial-time map from Boolean satisfiability instances to graphs that sends satisfiable inputs into the yes case and unsatisfiable inputs into the no case. The polynomial may depend on ε and η. An algorithm for the promise problem may behave arbitrarily on graphs in neither case. Since a 3-colorable set has an independent subset of at least one third its size, the displayed parameter restriction ensures disjoint cases. The paper’s already proved weaker theorem allows randomized reductions; that distinction must be retained when assessing a claimed resolution.',question_type='yes_no',answer_criterion='Prove the stated gap NP-hardness for every fixed admissible ε,η, with a reduction and its completeness and soundness guarantees, or refute the universal hardness assertion. If a claimed hardness result uses randomized reductions, state that convention explicitly and distinguish it from deterministic NP-hardness. A polynomial-time algorithm would contradict the deterministic hardness claim under P≠NP; without a complexity separation, it alone is not a logical refutation of NP-hardness.',context_blocks=[b('Nearly all vertices can receive three colors in the yes case','Deleting at most an η fraction of vertices must leave a properly 3-colorable graph. The input need not be exactly 3-colorable.', 'primary'),b('The no case is stronger than needing many colors','Every independent set must occupy less than an ε fraction of the entire graph. Merely proving that no almost-spanning subgraph can be colored with a fixed number of colors does not give this guarantee.', 'primary'),b('The source proves a weaker gap','For every fixed k, the paper obtains a positive δ such that it is hard, under randomized reductions, to distinguish almost 3-colorability from failure to k-color all but a δ fraction of vertices. Conjecture 23 asks for the substantially stronger independent-set soundness condition.', 'primary'),b('The consequence reaches Vertex Cover','The complement of an independent set is a vertex cover. The requested gap would imply hardness of approximating minimum Vertex Cover within 3/2−ζ for every fixed ζ>0, as the source explains. This consequence is motivation, not an additional target.', 'primary')],why='Would strengthen almost-coloring hardness enough to improve a central Vertex Cover approximation barrier, linking graph coloring promises with independent-set soundness.',references=refs,progress=[dict(date='2023',text='Theorem 1 establishes the almost-coloring gap under randomized reductions; Conjecture 23 asks for no independent set of any prescribed small positive fractional size.',citation='primary')],status='source_open',status_note='The full conjecture, its definition of induced coloring and the weaker proved theorem were checked. Subsequent-result searches through 12 September 2026, including the publisher abstract of the related MFCS 2025 matrix-completion paper, did not locate this stronger independent-set gap. That later abstract is not evidence of a resolution.',model_self_contained=True,requires_context=False,importance=imp(c,'A graph-coloring hardness strengthening with a concrete consequence for the Vertex Cover approximation threshold.'),review_note='Restored yes and no cases, vertex fractions, fixed parameters and the admissible promise range. Distinguished the independent-set conjecture from the weaker randomized almost-coloring theorem and removed proposed proof routes.',working_summary=sm(['The yes instances become 3-colorable after deleting an arbitrarily small fixed fraction of vertices.','The no instances have no independent set occupying a prescribed small fixed fraction of all vertices.','The conjecture asks for NP-hardness of distinguishing these two cases.','The source proves a weaker almost-coloring gap with randomized reductions.','The stronger independent-set gap would improve hardness of approximating Vertex Cover toward a factor of three halves.'],['primary'])),notes=['Recovered iCol₃(G)≥1−η versus α(G)<ε|V|.','Defined induced colorability and made the promise cases disjoint.','Separated deterministic NP-hardness from the proved randomized-reduction theorem.','Retained the Vertex Cover consequence as motivation, with no solution hints.'],checked_sources=[refs[0]['url'],'https://doi.org/10.4230/LIPIcs.MFCS.2025.37'])

i='TCS-2658';_,c=card(i);refs=c['references'];refs[0]['locator']='RANDOM 2022, article 22: Definitions 1.2–1.3, Question 1.4 and the distinct Conjecture 1.5 read. m(A) is maximum geometric margin, not rank, discrepancy itself or matrix size.'
refs.extend([dict(id='hamming2025',title='Sign-Rank of k-Hamming Distance is Constant',authors='Mika Göös, Nathaniel Harms, Valentin Imbach, Dmitry Sokolov',year=2025,url='https://eccc.weizmann.ac.il/report/2025/060/',locator='Conference version, ECCC revision 1 dated 31 March 2026: Theorems 1.1–1.2 and Open Problem 1.3 read. The Hamming-distance family has sign-rank 2^{O(k)}, but the general margin-versus-sign-rank question remains explicitly open.'),dict(id='sign_rank2026',title='A Z₂–Topological Framework for Sign-rank Lower Bounds',authors='Florian Frick, Kaave Hosseini, Aliaksei Vasileuski',year=2026,url='https://eccc.weizmann.ac.il/report/2026/056/',locator='ECCC revision 1, 12 April 2026: introduction and Gap Hamming Distance definition read. The lower bounds apply to a partial sign matrix, whose unspecified entries distinguish it from the total matrices in this card.')])
save(i,dict(title='Does a constant margin force bounded sign-rank?',formal='For every real ρ∈(0,1], does there exist a finite integer d(ρ), independent of matrix dimensions, such that every finite sign matrix A with margin m(A)≥ρ has sign-rank at most d(ρ)? This is the dimension-free bounding-function question written in the source as rank±(A)≤η(m(A)^{−1}); no polynomial or computable bound on η is requested.',definitions='A sign matrix A∈{−1,+1}^{r×s} has positive finite numbers r,s of rows and columns and has every entry specified. Its sign-rank rank±(A) is the least D≥1 for which there are unit vectors u₁,…,uᵣ,v₁,…,vₛ∈ℝᴰ with Aᵢⱼ⟨uᵢ,vⱼ⟩>0 for all i,j. Equivalently it is the minimum real rank of a matrix B satisfying AᵢⱼBᵢⱼ>0 entrywise; zero entries do not realize either sign. The margin m(A) is the supremum, over such unit-vector representations in all finite dimensions D, of min_{i,j} Aᵢⱼ⟨uᵢ,vⱼ⟩. It lies in (0,1]. In optimizing margin, the representation dimension is unrestricted; the representation of least dimension need not maximize margin. The requested d may grow arbitrarily rapidly as ρ tends to zero, but for each fixed positive ρ it must bound all matrix sizes. Equivalently, one can use a finite nondecreasing bounding function η:[1,∞)→ℕ. This uniform bounded-margin interpretation is explicitly restated in the later source’s Open Problem 1.3. Matrices with missing or promise-restricted entries are excluded.',question_type='yes_no',answer_criterion='Prove a finite size-independent bound d(ρ) for every positive margin threshold ρ, or prove there is a fixed ρ>0 and a sequence of fully specified finite sign matrices with margins at least ρ and unbounded sign-ranks. No efficient procedure for producing the low-dimensional representation is required. Unbounded sign-rank with margins tending to zero, or only for partial matrices, does not refute the statement.',context_blocks=[b('Dimension and separation are different geometric resources','Rows can be represented as points and columns as oriented hyperplanes through the origin. Sign-rank minimizes the ambient dimension; margin instead maximizes the smallest normalized separation from any hyperplane.', 'primary'),b('A size-dependent bound is already known','The source recalls a bound of order m(A)^{−2}log N for an N×N matrix. The open question is whether any dependence on N can be removed, even at the cost of an arbitrarily worse dependence on margin.', 'primary'),b('The reverse implication fails','Small sign-rank need not imply a large margin. Thus the card concerns the particular direction from a positive margin lower bound to bounded dimension.', 'primary'),b('The proposed Hamming-distance counterexample did not work','The later theorem shows that exact k-Hamming-distance matrices have sign-rank bounded by 2^{O(k)}, independently of input length. It refutes the particular growing-rank conjecture proposed alongside Question 1.4, while restating the general question as open.', 'hamming2025'),b('Partial matrices require separate treatment','The April 2026 work obtains strong lower bounds for a Gap Hamming Distance promise problem. Its matrix leaves intermediate distances unspecified, so it does not give a fully specified constant-margin counterexample to the present statement.', 'sign_rank2026')],why='Asks whether robust high-dimensional point–halfspace representations can always be replaced by bounded-dimensional representations, connecting geometric learning parameters with communication complexity.',references=refs,progress=[dict(date='2022',text='The source presents the qualitative margin-to-sign-rank bound as Question 1.4 and separately conjectures growing sign-rank for a hypercube family.',citation='primary'),dict(date='2025',text='The Hamming-distance family is proved to have constant sign-rank for fixed distance, refuting that proposed counterexample.',citation='hamming2025'),dict(date='2026-03-31',text='The revised conference version still explicitly asks the full margin-versus-sign-rank question.',citation='hamming2025'),dict(date='2026-04-12',text='New topological lower bounds treat partial Gap Hamming Distance matrices, not a total constant-margin counterexample.',citation='sign_rank2026')],status='source_open',status_note='The primary definitions and question were matched to the explicit open restatement in the March 2026 conference-version revision. April 2026 partial-matrix progress was checked separately. No total-matrix resolution was located through 12 September 2026.',model_self_contained=True,requires_context=False,importance=imp(c,'A qualitative relationship between two fundamental geometric complexity parameters, with consequences for learning and communication.'),review_note='Identified m(A), defined sign-rank and normalized margin, and made the size-independent quantifiers explicit. Updated the failed Hamming-distance counterexample without confusing it with a resolution of the general question.',working_summary=sm(['A sign matrix can be represented by points and separating hyperplanes.','Its margin measures how far every point stays from every relevant hyperplane after normalization.','Its sign-rank is the smallest dimension of any representation with the correct signs.','The question asks whether a fixed positive margin forces a dimension bound independent of matrix size.','Recent work disproves a proposed Hamming-distance counterexample but explicitly leaves the general question open.'],['primary','hamming2025','sign_rank2026'])),notes=['Defined the unidentified invariant m(A) and distinguished its optimization from sign-rank.','Made the uniform positive-margin quantifiers and total-matrix restriction explicit.','Checked the March 2026 revision that disproves the suggested example but restates the general question.','Distinguished April 2026 partial-matrix lower bounds.'],checked_sources=[r['url'] for r in refs])

i='TCS-2664';_,c=card(i);refs=c['references'];refs[0]['locator']='ITCS 2022, article 53: Definition 10, Proposition 11 and Conjecture 2 on page 53:6. The saved heading belongs to Conjecture 2, despite the imported locator naming Conjecture 1.'
refs.append(dict(id='full',title='Convex Influences — full version',authors='Anindya De, Shivam Nadimpalli, Rocco A. Servedio',year=2021,url='https://arxiv.org/abs/2109.03107',locator='Full version linked from the author’s publication page; arXiv has only v1, 7 September 2021. Checked the low-influence-direction question and the exact zero-influence characterization.'))
save(i,dict(title='Can a low-influence direction be removed from a convex set?',formal='Does there exist a function τ:(0,1)→[0,1] with lim_{ε→0⁺}τ(ε)=0 such that the following holds for every n≥1, every centrally symmetric convex Borel set K⊆ℝⁿ, every unit vector v and every ε∈(0,1)? If Inf_v[K]≤ε, then there exists a centrally symmetric convex Borel set C⊆v⊥ such that γₙ(K △ (C+ℝv))≤τ(ε). The same τ must work in all dimensions and for all such sets and directions.',definitions='γₙ is standard Gaussian probability measure, the law of X with independent N(0,1) coordinates. Central symmetry means K=−K, with symmetry about the origin. Convexity means tx+(1−t)y∈K for x,y∈K and t∈[0,1]. Write 1_K for the indicator of K. The convex influence in a Euclidean unit direction v is Inf_v[K]=(1/√2) E[1_K(X)(1−⟨v,X⟩²)]. This is nonnegative for centrally symmetric convex K. The orthogonal subspace is v⊥={y:⟨v,y⟩=0}, and C+ℝv={y+tv:y∈C,t∈ℝ} is a cylinder whose membership depends only on the projection x−⟨v,x⟩v. The symmetric difference K△L consists of points in exactly one of K and L, so its Gaussian measure is the probability that their membership indicators disagree. Empty sets and the whole space are permitted. No lower or upper bound away from zero or one is imposed on γₙ(K), and no bound on total influence is assumed.',question_type='yes_no',answer_criterion='Prove a single modulus τ tending to zero that bounds the Gaussian approximation error uniformly over the stated sets, dimensions and directions, or prove that no such modulus exists. Equivalently for a negative answer, exhibit a sequence with directional influence tending to zero while its Gaussian distance from every symmetric convex cylinder in that direction stays bounded below by a positive constant. A dimension-dependent modulus or a cylinder in some other direction does not suffice.',context_blocks=[b('Removing a direction means becoming cylindrical','The approximating set is unrestricted along v. Moving any distance parallel to v cannot change membership, although membership may depend arbitrarily on the orthogonal projection.'),b('The influence is a Gaussian second-moment statistic','The definition compares membership with the squared coordinate in direction v. It differs from boundary surface area, resampling influence and the total influence summed over directions.', 'primary'),b('Zero influence already has an exact characterization','Proposition 11 says that zero influence is equivalent, up to Gaussian null sets, to membership being independent of the coordinate along v. The conjecture asks for a dimension-free robust form of that statement.', 'primary'),b('The nearby junta conjecture is a different claim','Conjecture 1 controls the number of relevant directions using total influence. This card is Conjecture 2: one specified direction has small influence, and only that direction must be removed.', 'primary')],why='Would make convex influence a robust measure of whether a Gaussian direction matters, strengthening the analogy between symmetric convex sets and Boolean functions with irrelevant variables.',references=refs,progress=[dict(date='2022',text='The source proves the exact zero-influence characterization and states the dimension-free approximate version as Conjecture 2.',citation='primary')],status='source_open',status_note='The correct numbered conjecture, influence normalization and zero-influence statement were recovered. The author’s full-version link and arXiv revision history were checked, and subsequent-result searches through 12 September 2026 located no resolution of the dimension-free directional statement.',model_self_contained=True,requires_context=False,importance=imp(c,'A robust structural interpretation of a Gaussian influence parameter, relevant to dimension reduction and learning symmetric convex sets.'),review_note='Corrected the locator from Conjecture 1 to Conjecture 2, replaced the qualitative heading with the exact universal modulus, and defined Gaussian error, normalization and cylindrical independence.',working_summary=sm(['The problem concerns symmetric convex sets under standard Gaussian measure.','A specified direction has small convex influence, measured by a normalized second-moment statistic.','The conjecture asks whether the set is close to a symmetric convex cylinder that ignores this direction.','The approximation error must tend to zero with influence independently of dimension.','The exact zero-influence case is known, while the robust dimension-free statement remains the source’s Conjecture 2.'],['primary','full'])),notes=['Recovered Conjecture 2 rather than the nearby total-influence junta conjecture.','Defined directional convex influence with the 1/√2 normalization.','Specified the universal modulus, Gaussian symmetric-difference error and fixed cylinder direction.','Checked the full version and its revision history; removed technique suggestions.'],checked_sources=[r['url'] for r in refs]+['https://www.cs.columbia.edu/~rocco/papers/itcs22.html'])
